import{_ as r,c as e,o as p,ae as l}from"./chunks/framework.C-JRAr_X.js";const c=JSON.parse('{"title":"11. 2025 지급단가","description":"","frontmatter":{"title":"11. 2025 지급단가"},"headers":[],"relativePath":"manual/11._2025_지급단가.md","filePath":"manual/11._2025_지급단가.md"}'),n={name:"manual/11._2025_지급단가.md"};function d(s,t,o,g,a,i){return p(),e("div",null,t[0]||(t[0]=[l('<p>2025. 04.</p><table><colgroup><col style="width:100%;"></colgroup><thead><tr><th><p><strong>[지급단가 적용 기준]</strong></p></th></tr></thead><tbody><tr><td><p>본 기준은 <strong>특정 분야에 한해 예외적으로 지급단가를 규정</strong>한 것입니다.</p></td></tr><tr><td><p>재단의 예산 집행은 해당 분야에 대해서는 본 기준을 따라야 하며,</p></td></tr><tr><td><p>그 외의 분야에는 별도의 지급단가가 정해져 있지 않습니다.</p></td></tr><tr><td><p>따라서 <strong>규정된 지급단가가 없는 경우, 시중가격(견적 비교 등)을 적용</strong>해야 합니다.</p></td></tr><tr><td><p>또한, 아래 공통 기준은 모든 지급단가에 적용되므로 유의하시기 바랍니다.</p></td></tr><tr><td><p>♣ 지급단가 기준표는 지급 가능한 최대 한도액을 의미합니다.</p></td></tr><tr><td><p>♣ 한도액을 초과하여 지급할 수 없으며, 한도액 이하로 지급하는 것은 가능합니다.</p><p>※ 단, 단기근무자의 인건비 지급기준은 감액할 수 없으며, 서울시 생활임금을 준수해야 합니다.</p></td></tr><tr><td><p>♣ 부득이한 사유로 지급단가 기준 초과가 필요한 경우, 대표이사의 방침을 받은 후 지급할 수 있습니다.</p><p>※ 단, 이 경우에도 「청탁금지법」을 준수해야 하며, <strong>지급 사유를 반드시 기재</strong>해야 합니다.</p></td></tr><tr><td><p>♣ 준용한 지침의 기준단가가 변동될 경우, 별도의 추가 방침 없이 변경된 기준단가를 적용합니다.</p></td></tr><tr><td><p>♣ 수탁사업의 경우, 해당 사업지침에서 별도의 기준을 정한다면, 해당 지침을 우선적으로 따릅니다.</p></td></tr></tbody></table><p>강사료 공통기준</p><p><strong>1</strong></p><ul><li><p>강의시간 산출시 최초 1시간은 1시간 도달 시, 초과시간은 30분 이상 시 1시간으로 산출 (30분 미만은 강의시간 미포함)</p></li><li><p>동일한 강사가 중복 출강 시 최초 1시간 단가를 인정하는 경우</p><ul><li><p>원칙 : 일자별 산정 방식</p></li><li><p>강의일자가 다른 경우에는 강사료 지급 가능</p></li><li><p>강의일자가 같은 경우에도 대상이 다르거나, 대상이 같더라도 다른 내용(주제)으로 강의하는 경우 강사료 지급 가능</p></li></ul></li><li><p>동일 강사가 중복 출강 시 단가를 인정하는 경우</p></li></ul><table><colgroup><col style="width:20%;"><col style="width:19%;"><col style="width:19%;"><col style="width:19%;"><col style="width:19%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>강사(지급주체)</strong></p></th><th style="text-align:center;"><p><strong>강의일자</strong></p></th><th style="text-align:center;"><p><strong>교육대상</strong></p></th><th style="text-align:center;"><p><strong>교육내용(주제)</strong></p></th><th style="text-align:center;"><p><strong>지급대상 여부</strong></p></th></tr></thead><tbody><tr><td rowspan="4"><p>동일</p></td><td rowspan="3"><p>동일</p></td><td style="text-align:center;"><p>동일</p></td><td style="text-align:center;"><p>동일</p></td><td style="text-align:center;"><p>×</p></td></tr><tr><td style="text-align:center;"><p>동일</p></td><td style="text-align:center;"><p>다름</p></td><td style="text-align:center;"><p>○</p></td></tr><tr><td style="text-align:center;"><p>다름</p></td><td style="text-align:center;"><p>동일</p></td><td style="text-align:center;"><p>○</p></td></tr><tr><td style="text-align:center;"><p>다름</p></td><td colspan="2" style="text-align:center;"><p>불문</p></td><td style="text-align:center;"><p>○</p></td></tr><tr><td style="text-align:center;"><p>다름</p></td><td colspan="3" style="text-align:center;"><p>불문</p></td><td style="text-align:center;"><p>○</p></td></tr></tbody></table><p>강사료 단가</p><p><strong>2</strong></p><h2 id="가-특강-및-일반강의-지급단가" tabindex="-1"><strong>가. 특강 및 일반강의 지급단가</strong> <a class="header-anchor" href="#가-특강-및-일반강의-지급단가" aria-label="Permalink to &quot;**가. 특강 및 일반강의 지급단가**&quot;">​</a></h2><table><colgroup><col style="width:4%;"><col style="width:7%;"><col style="width:7%;"><col style="width:10%;"><col style="width:27%;"><col style="width:43%;"></colgroup><thead><tr><th colspan="2" rowspan="2"><p><strong>구 분</strong></p></th><th rowspan="2"><p><strong>지급 기준</strong></p></th><th rowspan="2" style="text-align:center;"><p><strong>지급단가 (만원)</strong></p></th><th colspan="2"><p><strong>적용대상 (청탁금지법 적용 유무로 구분)</strong></p></th></tr><tr><th><p><strong>공공분야 (공직자 등)</strong></p></th><th style="text-align:center;"><p><strong>민간분야</strong></p></th></tr></thead><tbody><tr><td rowspan="8"><p>특 강</p><p>및</p><p>일 반 강 의</p></td><td></td><td><p>기본 1시간</p></td><td style="text-align:center;"><p><strong>40</strong></p></td><td><p>∘ 장관급*, 광역자치단체장*</p><p>∘ 대학총장(장관급)</p><p>∘ 국회의원*</p></td><td rowspan="4"><p>∘ 전직 장관급 및 대학총장</p><p>∘ 전직 국회의원 및 광역자치단체장</p><p>∘ 대기업 회장</p><p>∘ 활동경력 30년 이상의 문화·예술, 체육, 언론, 종교, 시민단체 전문직 종사자 및 이에 준하는 해당분야 최고 전문가로 대표이사가 필요하다고 인정하는 경우</p></td></tr><tr><td rowspan="2"><p>특(1)</p></td><td></td><td style="text-align:center;"></td><td rowspan="2"></td></tr><tr><td></td><td style="text-align:center;"></td></tr><tr><td></td><td style="text-align:center;"><p>초과</p></td><td style="text-align:center;"><p><strong>20</strong></p></td><td></td></tr><tr><td></td><td><p>기본 1시간</p></td><td style="text-align:center;"><p><strong>30</strong></p></td><td><p>∘ 차관급, 대학총장(차관급)</p><p>∘ 기초자치단체장</p><p>∘ 공직유관단체장</p></td><td rowspan="4"><p>∘ 전직 차관(급)</p><p>∘ 전직 공기업 대표</p><p>∘ 전직 기초자치단체장</p><p>∘ 활동경력 20년 이상의 문화·예술, 체육, 언론, 종교, 시민단체 전문직 종사자, 이에 준하는 해당분야 최고 전문가로 대표이사가 필요하다고 인정하는 경우</p></td></tr><tr><td rowspan="2"><p>특(2)</p></td><td></td><td style="text-align:center;"></td><td rowspan="2"></td></tr><tr><td></td><td style="text-align:center;"></td></tr><tr><td></td><td style="text-align:center;"><p>초과</p></td><td style="text-align:center;"><p><strong>15</strong></p></td><td></td></tr></tbody></table><table><colgroup><col style="width:4%;"><col style="width:7%;"><col style="width:7%;"><col style="width:10%;"><col style="width:27%;"><col style="width:43%;"></colgroup><thead><tr><th colspan="2" rowspan="2"><p><strong>구 분</strong></p></th><th rowspan="2"><p><strong>지급 기준</strong></p></th><th rowspan="2"><p><strong>지급단가 (만원)</strong></p></th><th colspan="2"><p><strong>적용대상 (청탁금지법 적용 유무로 구분)</strong></p></th></tr><tr><th><p><strong>공공분야 (공직자 등)</strong></p></th><th style="text-align:center;"><p><strong>민간분야</strong></p></th></tr></thead><tbody><tr><td rowspan="10"><p>특 강</p><p>및</p><p>일 반 강 의</p></td><td rowspan="2"><p>일반 (1)</p></td><td><p>기본 1시간</p></td><td><p><strong>25</strong></p></td><td rowspan="2"><p>∘ 4급 이상 공무원</p><p>∘ 지방의회의원</p><p>∘ 대학의 교수</p><p>∘ 공직유관단체 임원 (출연연구기관 부연구위원 이상)</p><p>∘ 언론인</p></td><td rowspan="2"><p>∘ 전직 4급 이상 공무원</p><p>∘ 전직 지방의회의원(의장 포함)</p><p>∘ 유명 예술인·종교인, 이와 유사한 분야의 유명 인사</p><p>∘ 기업‧기관‧단체의 임원, 중역</p><p>∘ 변호사, 변리사, 공인회계사, 감정평가사, 의사, 기술사, 세무사 등 전문자격증을 가진 자로서 5년 이상 실무경력자</p><p>∘ 박사학위 취득 후 해당분야 5년 이상 실무 경력자 (취미·소양·외국어·전산 강사 제외)</p><p>∘ 국가대표 지도자 및 국가대표 출신 강사</p><p>∘ 활동경력 10년 이상의 문화·예술, 체육, 언론, 종교, 시민단체 전문직 종사자, 이에 준하는 해당분야 전문가로 대표이사가 필요하다고 인정하는 경우</p></td></tr><tr><td><p>초과</p></td><td><p><strong>12</strong></p></td></tr><tr><td rowspan="2"><p>일반 (2)</p></td><td><p>기본 1시간</p></td><td><p><strong>15</strong></p></td><td rowspan="2"><p>∘ 5급 이하 공무원</p><p>∘ 대학의 강사 등</p><p>∘ 공직유관단체 직원</p></td><td rowspan="2"><p>∘ 전직 5급 이하 공무원</p><p>∘ 중소기업 임원급, 기업‧기관‧단체의 부장급</p><p>∘ 체육지도사 1급이상 자격증 소지자 및 해당 교과분야(문화·예술 등) 3년 이상 강의 경력자</p><p>∘ 원어민 어학 강사(외국에서 태어나거나 외국국적을 취득한 자로서, 동일어권 국가에서 20년 이상 체류하고 고등교육을 이수한 자)</p><p>∘ 전문자격증을 가진 자로서 3년 이상 실무경력자</p><p>∘ 활동경력 7년 이상의 문화·예술, 체육, 언론, 종교, 시민단체 전문직 종사자, 이에 준하는 해당분야 전문가로 대표이사가 필요하다고 인정하는 경우</p></td></tr><tr><td><p>초과</p></td><td><p><strong>8</strong></p></td></tr><tr><td rowspan="2"><p>일반 (3)</p></td><td><p>기본 1시간</p></td><td style="text-align:center;"><p><strong>10</strong></p></td><td rowspan="2"><p>∘ 6급 이하 공무원 및 이에 준하는 자</p><p>∘ 공직 유관단체 직원</p></td><td rowspan="2"><p>∘ 외국어, 전산 등 강사</p><p>∘ 활동경력 5년 이상의 문화·예술, 체육, 언론, 종교, 시민단체 전문직 종사자 및 이에 준하는 해당분야 전문가로 대표이사가 필요하다고 인정하는 경우</p><p>∘ 체육, 레크리에이션 등 취미소양 강사로서 해당 분야 5년 이상(외부 경력 포함) 또는 3년 이상(자치인재원 경력) 강의 경력자</p></td></tr><tr><td><p>초과</p></td><td style="text-align:center;"><p><strong>5</strong></p></td></tr><tr><td rowspan="2"><p>일반 (4)</p></td><td><p>기본 1시간</p></td><td style="text-align:center;"><p><strong>8</strong></p></td><td rowspan="2"><p>∘ 기타 상기 등급에 속하지 아니하는 자</p></td><td rowspan="2"><p>∘ 활동경력 3년 이상의 문화·예술, 체육, 언론, 종교, 시민단체 전문직 종사자 및 이에 준하는 해당분야 전문가로 대표이사가 필요하다고 인정하는 경우</p><p>∘ 문화·예술, 체육, 레크리에이션 등 취미소양 강사로서 해당 분야 3년 이상(외부 경력 포함) 강의 경력자</p></td></tr><tr><td style="text-align:center;"><p>초과</p></td><td style="text-align:center;"><p><strong>4</strong></p></td></tr><tr><td rowspan="2"><p>보조 강사</p></td><td><p>기본 1시간</p></td><td style="text-align:center;"><p><strong>6</strong></p></td><td colspan="2" rowspan="2"><p>∘ 각종 교육 및 강의 운영(실기실습 등) 보조자</p></td></tr><tr><td style="text-align:center;"><p>초과</p></td><td style="text-align:center;"><p><strong>4</strong></p></td></tr></tbody></table><p>주) 1. 세미나, 심포지엄, 패널 토의 기조연설자 및 주제발표자 등에 대한 수당은 상기 기준 적용</p><ol start="2"><li><p>‘공직자 등’이란「청탁금지법」제2조 제2호에 해당하는 자를 말하며, 같은 법 시행령 제25조(수수가 제한되는 외부강의 등의 사례금 상한액) 규정과 소속기관별 공무원 행동강령이 적용됨</p></li><li><p>‘공직자 등’의 강사수당에는 강의료, 원고료, 출연료 등 명목에 관계없이 일체의 사례금을 포함함. 다만 소속기관에서 교통 비, 숙박비, 식비 등 여비를 지급받지 못한 경우 공무원여비규정 등 기관별로 적용하는 여비규정 내에서 실비 수준으로 제 공되는 교통비, 숙박비 및 식비는 사례금에 포함되지 않음</p></li><li><p>체육, 레크리에이션 등 취미소양 강사는 취미소양을 위해 출강하는 경우를 말하며, 기타 특강, 일반강좌, 공연 등의 경우에 는 달리 적용할 수 있음</p></li><li><p>국립대학이면서 공직유관단체에도 해당되는 학교(국가대학법인으로 설립하는 국립대학인 서울대학교, 인천대학교 등)는 대학의 교수 기준 적용</p></li><li><p>‘출연연구기관 부연구위원 이상’ 기준</p></li></ol><p>가. 출연연구기관 : ｢정부출연연구기관 등의 설립・운영 및 육성에 관한 법률｣, ｢과학기술분야 정부출연연구기관 등의 설 립・운영 및 육성에 관한 법률｣, ｢지방자치단체출연 연구원의 설립 및 운영에 관한 법률｣에 따라 설립된 연구를 주된 목적으로 하는 기관(KDI, 한국지방행정연구원, 경기연구원 등)</p><p>※ ｢지방자치단체 출자・출연 기관의 운영에 관한 법률｣의 기관은 적용 안 됨</p><p>나. 부연구위원 : ｢고등교육법｣ 제16조 및 시행령 제5조, ｢대학교원 자격기준 등에 관한 규정｣ 제2조의 별표 기준에 따 라 국공립·사립대학의 조교수에 준하는 자격 이상을 갖춘 자</p><ol start="7"><li><p>비대면 교육 강사수당의 경우 일반강의 강사수당에 준하여 지급</p></li><li><p>이러닝 콘텐츠 촬영 강사수당은 완성된 ‘촬영시간’ 기준(일 최대 6시간)으로 분류에 따라 일반강의 강사수당에 준하여 지급하며, 여비 및 원고료를 지급할 수 있음</p></li><li><p>저작권자의 강의(녹화, 온라인 송출 등) 동영상을 재이용 하고자 할 때에는 강사료 계약 시 동의를 얻어야 하며, 강사 미동의 시 해당 강의는 녹화 또는 저장하지 않음. 강의 동영상 활용 시 별도의 용역 계약을 맺어 진행 할 수 있음</p></li><li><p>정보화 교육과정(첨단기술) 강사; 일반교육 강사 지급기준 준용 가능</p></li><li><p>위 지급대상에 명시적으로 규정되지 않은 공공분야 종사자는「청탁금지법 시행령」「별표2」제2호의 적용기준에 따라 구분</p></li><li><p>위 기준에도 불구하고 교육과정 운영 및 강사 초빙의 특이한 사정 등을 감안, 「<u>청탁금지법」과 「같은 법 시행령」에 저촉되지</u> <u>않는 범위 내</u>에서 대표가 인정하는 자에 한하여 별도 방침에 따른 기준으로 지급 가능하며, 이 경우 초청한 그 사례에만 적용</p></li><li><p>상기 단가는 최대 한도액으로 하향집행 가능</p></li><li><p>강사료 외, 1시간 이상 교과목 편성 및 교재편찬용 제출원고, 각종 세미나, 토론회 등 교육운영에 주제와 관련된 원고료를 지급할 수 있음. 단, 공공분야 강사인 경우 원고료 미지급</p></li></ol><p>(강의 시간당 한글원고 원고료 A4 기준 6매분 까지 지급, 강사 1인에 대해서는 1주(5일)간 최대 40매 제한)</p><ol start="15"><li><p>일반강의 강사수당 적용대상 중 전문자격증 관련 인정 조건은 자격증과 관련된 강의를 하는 자에 한하여 해당 등급으로 인정</p></li><li><p>상기 단가는 지방자치인재개발원 단가를 준용함</p></li></ol><h1 id="나-퍼실리테이터-강사료-지급단가" tabindex="-1"><strong>나. 퍼실리테이터 강사료 지급단가</strong> <a class="header-anchor" href="#나-퍼실리테이터-강사료-지급단가" aria-label="Permalink to &quot;**나. 퍼실리테이터 강사료 지급단가**&quot;">​</a></h1><table><colgroup><col style="width:3%;"><col style="width:4%;"><col style="width:17%;"><col style="width:12%;"><col style="width:62%;"></colgroup><thead><tr><th colspan="2"><p><strong>구분</strong></p></th><th><p><strong>지급기준</strong></p></th><th style="text-align:center;"><p><strong>지급단가 (만원)</strong></p></th><th style="text-align:center;"><p><strong>지 급 대 상</strong></p></th></tr></thead><tbody><tr><td rowspan="16"><p>퍼 실 리 테 이 터</p></td><td></td><td rowspan="2"><p>최초 1시간</p></td><td rowspan="2" style="text-align:center;"><p><strong>23</strong></p></td><td><p>∘ 전문교육기관 15년이상 전문강사 경력자</p></td></tr><tr><td rowspan="2"><p>(1)</p></td><td rowspan="2"><p>∘ 기업 대표(급) 및 이에 준하는 자로 대표가 필요하다고 인정한 경우</p></td></tr><tr><td rowspan="2"><p>초과(매시간)</p></td><td rowspan="2" style="text-align:center;"><p><strong>15</strong></p></td></tr><tr><td></td><td><p>∘ 전․현직 장관(급) 이상 및 이에 준하는 자</p></td></tr><tr><td></td><td rowspan="2"><p>최초 1시간</p></td><td rowspan="2" style="text-align:center;"><p><strong>20</strong></p></td><td><p>∘ 전문교육기관 10년이상 전문강사 경력자</p></td></tr><tr><td rowspan="2"><p>(2)</p></td><td rowspan="2"><p>∘ 기업 임원(급) 및 이에 준하는 자</p></td></tr><tr><td rowspan="2"><p>초과(매시간)</p></td><td rowspan="2" style="text-align:center;"><p><strong>13</strong></p></td></tr><tr><td></td><td><p>∘ 전․현직 차관(급) 및 이에 준하는 자</p></td></tr><tr><td></td><td rowspan="2"><p>최초 1시간</p></td><td rowspan="2" style="text-align:center;"><p><strong>15</strong></p></td><td><p>∘ 전문교육기관 5년이상 전문강사 경력자</p></td></tr><tr><td rowspan="2"><p>(3)</p></td><td rowspan="2"><p>∘ 대학 교수 이상</p></td></tr><tr><td rowspan="2"><p>초과(매시간)</p></td><td rowspan="2" style="text-align:center;"><p><strong>10</strong></p></td></tr><tr><td></td><td><p>∘ 전․현직 3급 이상 및 이에 준하는 자</p></td></tr><tr><td></td><td rowspan="2"><p>최초 1시간</p></td><td rowspan="2" style="text-align:center;"><p><strong>12</strong></p></td><td><p>∘ 전문교육기관 5년미만 전문강사 경력자</p></td></tr><tr><td rowspan="2"><p>(4)</p></td><td rowspan="2"><p>∘ 대학 전임강사(급) 이상</p><p>∘ 전․현직 4급 이하 및 이에 준하는 자</p></td></tr><tr><td rowspan="2"><p>초과(매시간)</p></td><td rowspan="2" style="text-align:center;"><p><strong>8</strong></p></td></tr><tr><td></td><td><p>∘ 예술분야 전문가로 역량개발 및 협업 관련 경험을 가진 자</p></td></tr></tbody></table><p>주) 1. 퍼실리테이터가 청탁금지법 규정에 따른 공직자등으로서 자신의 직무과 관련한 외부강의 시 <u>청탁금지법 상 상한액 및 소속</u> <u>기관별 공무원 행동강령 범위 내</u>에서 지급</p><ol start="2"><li><p>FT 요건: 집단을 관찰 및 파악하여 역량개발을 위한 피드백을 제공하는 촉진자로, 이에 걸맞은 경력 및 역량을 지닌 자</p></li><li><p>퍼실리테이터 요건(역할) : 실습과정을 관찰하고 부족 역량을 파악하여 역량개발을 위한 피드백을 제공하는 학습촉진자</p></li><li><p>퍼실리테이터 자격 : 법령에 따른 전문교육기관에 속한 전문강사로 활동한 경력이 있는 자로 구분 별 연차에 해당하는 자</p></li><li><p>비대면 교육 시에도 동일하게 지급</p></li><li><p>상기 단가는 서울시 인재개발원 단가를 준용함</p></li></ol><p><strong>다. 다수인 강사료 지급단가 * 음악 및 무용 등 다수 참여 필요 교육</strong></p><table><colgroup><col style="width:13%;"><col style="width:28%;"><col style="width:28%;"><col style="width:28%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>출강인원</strong></p><p><strong>시간</strong></p></th><th style="text-align:center;"><p><strong>5인 이하</strong></p></th><th style="text-align:center;"><p><strong>6인 ~ 10인</strong></p></th><th style="text-align:center;"><p><strong>11인 이상</strong></p></th></tr></thead><tbody><tr><td style="text-align:center;"><p>2시간 미만</p></td><td style="text-align:center;"><p>500,000원</p></td><td style="text-align:center;"><p>700,000원</p></td><td style="text-align:center;"><p>900,000원</p></td></tr><tr><td style="text-align:center;"><p>2시간 이상</p></td><td style="text-align:center;"><p>700,000원</p></td><td style="text-align:center;"><p>900,000원</p></td><td style="text-align:center;"><p>1,100,000원</p></td></tr></tbody></table><p>주) 1. 교육 운영상 필요한 경우 시중 출연료를 감안하여 30% 범위 내에서 위 기준을 상향조정 지급할 수 있음</p><ol start="2"><li><p>단체공연의 경우 사회적 지명도에 따라 별도 시중단가 적용 가능</p></li><li><p>상기 단가는 지방자치인재개발원 단가를 준용함</p></li></ol><p>위원회 참석수당</p><p><strong>2</strong></p><p><strong>가. 자문회의 지급단가</strong></p><table><colgroup><col style="width:8%;"><col style="width:6%;"><col style="width:18%;"><col style="width:39%;"><col style="width:27%;"></colgroup><thead><tr><th><p><strong>구분</strong></p></th><th style="text-align:center;"><p><strong>단위</strong></p></th><th><p><strong>지급단가</strong></p></th><th style="text-align:center;"><p><strong>지급기준</strong></p></th><th style="text-align:center;"><strong>비 고</strong></th></tr></thead><tbody><tr><td><p><strong>위원회 참석비</strong></p></td><td><p><strong>일당</strong></p></td><td><p><strong>기본료 150,000원 초과 50,000원</strong></p></td><td><p>∘ 사업추진을 위한 전문가 및 관계자 자문</p><p>∘ 프로그램 개발 및 평가 등 전문성을 요하는 자문</p><p>∘ 정책 및 사업운영과 관련한 전문가 자문회의 등</p><p>∘ 초과는 2시간 이상 시 1일 1회에 한하여 지급</p></td><td><p>∘ 기본료: 최초 2시간 기준</p><p>∘ 최대 1시간까지 초과분 지급 가능</p><p>※ 1일 최대 3시간</p><p>※ 원격 회의시에도 동일하게 지급</p></td></tr></tbody></table><p>주) 1. 위원회 참석수당은「서울시 출자출연기관 예산편성 기준」의 “위원회 참석비” 준용</p><ol start="2"><li><p>해당 기관에 출자·출연한 국가기관 또는 서울시 소속 공무원이 각종 회의 등에 참여하는 경우 무보수 비상근 임원 여부에 관계없이 참석수당을 지급할 수 없음</p></li><li><p>임직원인 경우 직접 자기가 담당하는 사무뿐만 아니라 자기가 소속된 기관에서 설치된 위원회에 참여하는 경우에는 참석수당을 지급할 수 없음</p></li><li><p>다만 무보수 비상근 임직원이 참여하는 경우에는 내부규정에 따라 참석수당 지급 가능</p></li><li><p>자문회의 후 컨설팅 보고서를 재단에 별도 제출하는 경우 원고료 지급 기준에 준하여 지급 가능</p></li><li><p>회의 참석수당 지급은 참석자 명의 계좌로의 입금을 필수로 함</p></li><li><p>변호사, 회계사, 감정평가사, 건축가, 변리사 등 관련 전문가로부터 자문을 받는 경우 거래실례가격 등을 기준으로 자문료 지급 가능</p></li><li><p>관외거주 심사위원의 경우, &lt;7. 여비&gt; 국내여비의 교통비 및 숙박비를 한도 내에서 실비금액을 가산하여 지급할 수 있음. 단, 사전 품의 시 소요경비 증빙자료 첨부 필요</p></li></ol><h1 id="나-이사회-지급단가" tabindex="-1"><strong>나. 이사회 지급단가</strong> <a class="header-anchor" href="#나-이사회-지급단가" aria-label="Permalink to &quot;**나. 이사회 지급단가**&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>지급단가</strong></th><th style="text-align:center;"><strong>지급기준</strong></th><th style="text-align:center;"><strong>비고</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><strong>300,000원</strong></td><td style="text-align:center;">이사회 참석자의 “회당”</td><td style="text-align:center;">시간에 따른 초과 지급 없음</td></tr></tbody></table><p>주) 1. 당연직 이사·감사에게 이사회 참석수당 지급 불가 / 노동이사는 참석수당 지급 가능</p><ol start="2"><li><p>임원추천위원회 및 비상임 회계감사의 결산감사 시 이사회 참석수당 준용 지급 기준 적용</p></li><li><p>회의수당과 이사회 참석수당은「서울시 출자출연기관 예산편성 기준」을 적용</p></li><li><p>비상임 임원(당연직 이사·감사 제외)은 이사회 참석수당 30만원 지급 (화상회의 포함)</p></li><li><p>비상임 이사 및 감사가 이사회 외 위원회 등에 참여하는 경우에 위원회 참석수당에 근거하여 수당을 지급할 수 있음</p></li><li><p>이사회 지급단가는「서울시 출자출연기관 예산편성 기준」에 따름</p></li></ol><h1 id="다-심사수당-지급단가" tabindex="-1"><strong>다. 심사수당 지급단가</strong> <a class="header-anchor" href="#다-심사수당-지급단가" aria-label="Permalink to &quot;**다. 심사수당 지급단가**&quot;">​</a></h1><table><colgroup><col style="width:27%;"><col style="width:21%;"><col style="width:21%;"><col style="width:30%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>구 분</strong></p></th><th style="text-align:center;"><p><strong>지급기준</strong></p></th><th style="text-align:center;"><strong>지급단가</strong></th><th style="text-align:center;"><strong>비 고</strong></th></tr></thead><tbody><tr><td rowspan="10"><p>서류 심사</p></td><td style="text-align:right;"><strong>1 ~ 10건</strong></td><td style="text-align:right;"><strong>300,000원</strong></td><td rowspan="10"><p>∘ 원고 심사 시 단가 200% 적용 가능</p><p>- 공모 절차상 모든 접수 건에 대한 원고, 영상자료 등 다량의 자료를 검토하는 것이 불가피한 경우에 한함</p></td></tr><tr><td style="text-align:right;"><strong>11 ~ 31건</strong></td><td style="text-align:right;"><strong>400,000원</strong></td></tr><tr><td style="text-align:right;"><strong>31 ~ 60건</strong></td><td style="text-align:right;"><strong>650,000원</strong></td></tr><tr><td style="text-align:right;"><strong>61 ~ 100건</strong></td><td style="text-align:right;"><strong>950,000원</strong></td></tr><tr><td style="text-align:right;"><p><strong>101 ~ 150건</strong></p></td><td style="text-align:right;"><strong>1,250,000원</strong></td></tr><tr><td style="text-align:right;"><p><strong>151 ~ 200건</strong></p></td><td style="text-align:right;"><strong>1,550,000원</strong></td></tr><tr><td style="text-align:right;"><p><strong>201 ~ 300건</strong></p></td><td style="text-align:right;"><strong>1,800,000원</strong></td></tr><tr><td style="text-align:right;"><p><strong>301 ~ 400건</strong></p></td><td style="text-align:right;"><strong>2,050,000원</strong></td></tr><tr><td style="text-align:right;"><p><strong>401 ~ 500건</strong></p></td><td style="text-align:right;"><strong>2,300,000원</strong></td></tr><tr><td style="text-align:right;"><p><strong>501건 이상.</strong></p></td><td style="text-align:right;"><strong>2,500,000원</strong></td></tr></tbody></table><table><colgroup><col style="width:27%;"><col style="width:21%;"><col style="width:21%;"><col style="width:30%;"></colgroup><thead><tr><th style="text-align:center;"><p>토론 심사</p></th><th style="text-align:right;"><p><strong>기본료(최초2시간)</strong></p><p><strong>초과(매시간)</strong></p></th><th style="text-align:right;"><p><strong>150,000원</strong></p><p><strong>50,000원</strong></p></th><th><p>∘ 1일 상한액 450,000원</p></th></tr></thead><tbody></tbody></table><table><colgroup><col style="width:27%;"><col style="width:21%;"><col style="width:21%;"><col style="width:30%;"></colgroup><thead><tr><th><p>인터뷰 심사</p></th><th style="text-align:right;"><p><strong>기본료(최초2시간)</strong></p><p><strong>초과(매시간)</strong></p></th><th style="text-align:right;"><p><strong>150,000원</strong></p><p><strong>70,000원</strong></p></th><th><p>∘ 1일 상한액 570,000원</p></th></tr></thead><tbody></tbody></table><p>주) 1. 내부 임직원(이사 포함)에게는 다른 법령 등에 특별한 규정이 없는 한 심사수당을 지급할 수 없음</p><ol start="2"><li><p>관외거주 심사위원의 경우, &lt;7. 여비&gt; 국내여비의 교통비 및 숙박비를 한도 내에서 실비금액을 가산하여 지급 할 수 있음. 단, 사전 품의 시 소요경비 증빙자료 첨부 필요</p></li><li><p>서류심사는 온라인 및 현장 구분이 아닌, 건수를 기준으로 지급기준 적용</p></li><li><p>토론심사는 서류 및 인터뷰 심사 외에 별도의 회의·검토 과정을 운영할 경우 적용되는 단가임</p></li><li><p>온라인 토론심사 추진 시 동일한 기준으로 단가 책정</p></li><li><p>상기 단가는 최대 한도액으로 하향집행 가능</p></li></ol><h1 id="라-평가수당-지급단가" tabindex="-1"><strong>라. 평가수당 지급단가</strong> <a class="header-anchor" href="#라-평가수당-지급단가" aria-label="Permalink to &quot;**라. 평가수당 지급단가**&quot;">​</a></h1><table><colgroup><col style="width:27%;"><col style="width:21%;"><col style="width:21%;"><col style="width:30%;"></colgroup><thead><tr><th><p><strong>구 분</strong></p></th><th style="text-align:center;"><p><strong>지급기준</strong></p></th><th style="text-align:center;"><p><strong>지급단가</strong></p></th><th style="text-align:center;"><strong>비 고</strong></th></tr></thead><tbody><tr><td><p>평가수당</p></td><td style="text-align:right;"><p><strong>기본료(최초2시간)</strong></p><p><strong>초과(매시간)</strong></p></td><td><p><strong>150,000원</strong></p><p><strong>50,000원</strong></p></td><td><p>∘ 1일 상한액 450,000원</p></td></tr></tbody></table><p>주) 1. 평가 수당에는 평가서 작성비 포함되어 있음</p><p>2. 상기 단가는 최대 한도액으로 하향집행 가능</p><p>회의경비·행사실비보상금</p><p><strong>3</strong></p><h1 id="가-회의경비" tabindex="-1"><strong>가. 회의경비</strong> <a class="header-anchor" href="#가-회의경비" aria-label="Permalink to &quot;**가. 회의경비**&quot;">​</a></h1><table tabindex="0"><thead><tr><th><strong>구 분</strong></th><th><strong>단가</strong></th><th><strong>비 고</strong></th></tr></thead><tbody><tr><td>회의경비</td><td><strong>25,000원/인</strong></td><td>∘ 다과/식비 구분 없음, 회의비 통계목 사용</td></tr></tbody></table><p>주) 1. 내부 직원 간 회의 시 사용 불가 (노사협의회/산업안전보건협의회 제외)</p><p>2. 상기 단가는 최대 한도액으로 하향집행 가능</p><p>3. 사전에 의결된 회의에 소요되는 진행비로 다과, 음식물 제공 등 회의 개최에 통상적으로 소요되는 비용</p><h1 id="나-행사실비보상금" tabindex="-1"><strong>나. 행사실비보상금</strong> <a class="header-anchor" href="#나-행사실비보상금" aria-label="Permalink to &quot;**나. 행사실비보상금**&quot;">​</a></h1><table tabindex="0"><thead><tr><th><strong>구 분</strong></th><th><strong>단가</strong></th><th><strong>비 고</strong></th></tr></thead><tbody><tr><td>행사실비보상금</td><td><strong>9,000원/인</strong></td><td>∘ 다과/식비 구분 없음, 행사실비보상금 통계목 사용</td></tr></tbody></table><p>주) 1. 다수 참여자들 대상으로 하는 행사 진행 시, 다과비는 4,000원 적용 권고</p><p>2. 상기 단가는 최대 한도액으로 하향집행 가능</p><p>3. 행사에 참여하는 민간인에게 지급하는 급량비</p><p>용역제공 관련</p><p><strong>4</strong></p><h1 id="가-무대예술-기술지원-용역비·인건비-지급단가" tabindex="-1"><strong>가. 무대예술 기술지원 용역비·인건비 지급단가</strong> <a class="header-anchor" href="#가-무대예술-기술지원-용역비·인건비-지급단가" aria-label="Permalink to &quot;**가. 무대예술 기술지원 용역비·인건비 지급단가**&quot;">​</a></h1><p>① 일반크루</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>구 분</strong></th><th><strong>지급단가</strong></th><th><strong>비 고</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><strong>무대.조명(음향) 크루</strong></td><td><strong>170,000원</strong></td><td>∘ 한국물가정보 노임단가 ‘24년 9월 기준 일 단가</td></tr></tbody></table><p>주) 1. 용역계약 체결 시, 시간 단위로 단가 책정불가하며, 과업별 소요일자로 단가 책정</p><p>2. 근로계약 체결 시, 1일 8시간 기준으로 단가를 책정할 수 있으나 근로기준법 준수</p><p>② 무대예술전문인</p><table><colgroup><col style="width:33%;"><col style="width:23%;"><col style="width:43%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>구 분</strong></p></th><th style="text-align:center;"><strong>지급단가</strong></th><th style="text-align:center;"><strong>비 고</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><p>무대1급(무대, 기계, 음향, 조명 1급)</p></td><td style="text-align:right;"><strong>312,655원</strong></td><td rowspan="3"><p>∘ 한국물가정보 노임단가 ‘24년 9월 기준 일 단가</p><p>∘ 자격증 사본 등 관련 자료 첨부 필수</p></td></tr><tr><td style="text-align:center;"><p>무대2급(무대, 기계, 음향, 조명 2급)</p></td><td style="text-align:right;"><strong>247,818원</strong></td></tr><tr><td style="text-align:center;"><p>무대3급(무대, 기계, 음향, 조명 3급)</p></td><td style="text-align:right;"><strong>179,781원</strong></td></tr></tbody></table><p>주) 1. 용역계약 체결 시, 시간 단위로 단가 책정불가하며, 과업별 소요일자로 단가 책정</p><p>2. 근로계약 체결 시, 1일 8시간 기준으로 단가를 책정할 수 있으나 근로기준법 준수</p><h2 id="나-단기근무자-인건비-단가" tabindex="-1"><strong>나. 단기근무자 인건비 단가</strong> <a class="header-anchor" href="#나-단기근무자-인건비-단가" aria-label="Permalink to &quot;**나. 단기근무자 인건비 단가**&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>구 분</strong></th><th><strong>단 가</strong></th><th><strong>비 고</strong></th></tr></thead><tbody><tr><td>단기근무자(일용직)</td><td><strong>11,799원 (시급)</strong></td><td>∘ 서울시 2025년 생활임금 반영</td></tr></tbody></table><p>주) 1. 주휴수당, 사회보험가입 여부, 동시 다른 사업장 근무여부 확인 필수 (근로계약이므로 용역계약 형태로 체결 X)</p><p>2. 단기근로자는 근로자로 간주되므로, 근로기준법 준수 필수</p><h2 id="다-학술연구용역-단가" tabindex="-1"><strong>다. 학술연구용역 단가</strong> <a class="header-anchor" href="#다-학술연구용역-단가" aria-label="Permalink to &quot;**다. 학술연구용역 단가**&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;"><strong>구 분</strong></th><th style="text-align:right;"><strong>월 단가(25년)</strong></th><th><strong>비 고</strong></th></tr></thead><tbody><tr><td style="text-align:right;">책임연구원</td><td style="text-align:right;"><strong>월 3,705,904원</strong></td><td>∘ 당해 용역수행을 지휘/감독하며 결론을 도출하는 역할을 수행하는 자를 말하며, 대학교수 수준의 기능을 보유</td></tr><tr><td style="text-align:right;">연 구 원</td><td style="text-align:right;"><strong>월 2,841,638원</strong></td><td>∘ 책임연구원을 보조하는 자로서 대학 조교수 수준의 기능을 보유</td></tr><tr><td style="text-align:right;">연구보조원</td><td style="text-align:right;"><strong>월 1,899,539원</strong></td><td>∘ 통계처리·번역 등의 역할을 수행하는 자로서 해당 연구분야에 대해 조교 정도의 전문지식을 가진 자</td></tr><tr><td style="text-align:right;">보 조 원</td><td style="text-align:right;"><strong>월 1,424,702원</strong></td><td>∘ 타자, 계산, 원고정리 등 단순한 업무처리를 수행하는 자</td></tr></tbody></table><p>주) 1. 본 인건비 기준단가는 1개월을 22일로 하여 용역 참여율 50%로 산정한 것이며, 학술연구용역 계약 시에는 용역참여을 최대 50%까지 가능(단, 일반용역에서 학술연구용역 단가 기준만 준용할 경우 용역참여율 변경 가능)</p><ol start="2"><li><p>상기단가는 2025년도 기준단가이며, 2026년 이후의 단가산출은 상기단가를 기준으로 “연도별 소비자물가 등락률”(통계청 발표)을 반영하여 산정한다.</p></li><li><p>기획재정부 계약예규 예정가격작성기준(제26조제2항) 및 행정안전부 예규 「지방자치단체 입찰 및 계약집행기준」 제2장 예정가격 작성요령 〈별표2〉학술연구용역인건비 기준단가 참고</p></li><li><p>예규가 개정되면 재단의 학술연구용역 단가 기준도 개정된 사항으로 자동 변경</p></li><li><p>상기 단가는 근로기준법상 ‘근로자’에 해당하지 않는 인력(용역·프리랜서 등)에 한하여 적용해야 하며, 지속적·전속적 업무 수행으로 근로자로 간주되지 않도록 유의</p></li><li><p>상기 단가를 활용 시, ‘개월’ 단위로만 산출가능 하며, 1개월 이내의 용역계약은 참여율 수정으로만 산출</p></li></ol><h1 id="라-예술인-및-단체-공연료-전시료-창작의뢰비-별도-시중가-적용" tabindex="-1"><strong>라. 예술인 및 단체 공연료, 전시료, 창작의뢰비 : 별도 시중가 적용</strong> <a class="header-anchor" href="#라-예술인-및-단체-공연료-전시료-창작의뢰비-별도-시중가-적용" aria-label="Permalink to &quot;**라. 예술인 및 단체 공연료, 전시료, 창작의뢰비 : 별도 시중가 적용**&quot;">​</a></h1><p>여비 ▸세부내용 확인: <a href="https://www.law.go.kr/%EB%B2%95%EB%A0%B9/%EA%B3%B5%EB%AC%B4%EC%9B%90%20%EC%97%AC%EB%B9%84%20%EA%B7%9C%EC%A0%95" target="_blank" rel="noreferrer">[공무원 여비 규정 링크]</a> 클릭(별표1,2,3,4,9 중 필요한 부분 참조)</p><p><strong>5</strong></p><h1 id="가-국내여비" tabindex="-1"><strong>가. 국내여비</strong> <a class="header-anchor" href="#가-국내여비" aria-label="Permalink to &quot;**가. 국내여비**&quot;">​</a></h1><table><colgroup><col style="width:7%;"><col style="width:9%;"><col style="width:9%;"><col style="width:8%;"><col style="width:7%;"><col style="width:9%;"><col style="width:33%;"><col style="width:13%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>구분</strong></p></th><th><p><strong>철도운임</strong></p></th><th><p><strong>선박운임</strong></p></th><th style="text-align:center;"><p><strong>항공 운임</strong></p></th><th style="text-align:center;"><p><strong>자동차 운임</strong></p></th><th style="text-align:center;"><p><strong>일비 (1일당)</strong></p></th><th style="text-align:center;"><p><strong>숙박비(1박당)</strong></p></th><th style="text-align:center;"><p><strong>식비 (1일당)</strong></p></th></tr></thead><tbody><tr><td style="text-align:center;"><p>제1호</p></td><td><p>실비 (특실)</p></td><td><p>실비 (1등급)</p></td><td style="text-align:center;">실비</td><td style="text-align:center;"><p>실비</p></td><td style="text-align:center;"><strong>25,000</strong></td><td style="text-align:center;"><p>실비</p></td><td style="text-align:center;">25,000</td></tr><tr><td style="text-align:center;"><p>제2호</p></td><td><p>실비 (일반실)</p></td><td><p>실비 (2등급)</p></td><td style="text-align:center;">실비</td><td style="text-align:center;"><p>실비</p></td><td style="text-align:center;"><strong>25,000</strong></td><td style="text-align:center;"><p><strong>실비</strong></p><p><strong>(상한액: 서울특별시 100,000,</strong></p><p><strong>광역시 80,000, 그 밖의 지역은 70,000)</strong></p></td><td style="text-align:center;"><strong>25,000</strong></td></tr></tbody></table><p>주) 1. 여비지급 구분은 「공무원 여비 규정 별표1」 / 지급액은 「공무원 여비 규정 별표 2」에 따름</p><p><strong>나. 국외여비</strong> 여비지급 구분은 <u>「공무원 여비 규정 별표1」</u> , <u>「공무원 여비 규정 별표3」</u> , 지급액은 <u>「공무원 여비 규정 별표 4」</u>에 따름</p><h1 id="다-기타-적용사항" tabindex="-1"><strong>다. 기타 적용사항</strong> <a class="header-anchor" href="#다-기타-적용사항" aria-label="Permalink to &quot;**다. 기타 적용사항**&quot;">​</a></h1><ul><li>「공무원보수 등의 업무지침」상의 공무원 여비 업무처리기준 적용</li></ul><p>※ 실비 수준의 교통비·숙박비 실비에 한함</p><ul><li>공무원이 아닌 강사의 여비지급</li></ul><ul><li><p>여비지급 등급은 「공무원여비규정」 제30조 및 별표9에 의거 별표9의 4 또는 5에 해당</p></li><li><p>민간기업체의 임․직원: 공공기관 임․직원에 해당하는 직위에 맞추어 지급함을 원칙으로 하고, 불분명할 경우에는 「공무원여비 규정」 별표1의 제2호를 지급</p></li><li><p>기타 공무원이 아닌 자: 업무의 성격, 동반공무원의 직위 및 당해 공무원이 아닌 자의 경력을 고려하여 지급하되, 일반 기준은 「공무원여비규정」 별표1의 제2호를 적용</p></li></ul><ul><li>준용한 규정 및 지침의 단가가 변동될 경우 추가 방침 없이 변동된 금액으로 적용함</li></ul><p>원고료</p><p><strong>6</strong></p><h1 id="가-지급대상" tabindex="-1"><strong>가. 지급대상</strong> <a class="header-anchor" href="#가-지급대상" aria-label="Permalink to &quot;**가. 지급대상**&quot;">​</a></h1><table><colgroup><col style="width:24%;"><col style="width:75%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>기준</strong></p></th><th style="text-align:center;"><strong>세부 요건</strong></th></tr></thead><tbody><tr><td style="text-align:right;">지급대상</td><td><p>∘ 원고 집필자</p></td></tr><tr><td style="text-align:right;">대상원고</td><td><p>∘ 1시간 이상 강의, 교재 편찬(부교재 포함), 제출 원고</p><p>∘ 각종 세미나, 토론회 등 행사(교육)운영 주제와 관련된 원고</p><p>∘ 발간물, 창작물, 연재물, 전문가 지식수록, 전문가 칼럼, 평론, 현장취재 원고 등</p><p>∘ 교양, 에세이, 서간문, 논문 등(전문성이 요구되는 원고)</p></td></tr></tbody></table><p>주) 1. 재단직원에게 원고료 지급 시 기준액의 50%만 지급 (원고청탁 업무 관계자는 지급 대상에서 제외)</p><ol start="2"><li>청탁금지법에 따른 공직자등 출강강사의 경우 원고료 미지급(다만, 법제2조제2항 다목 및 라목의 각급 학교의 장과 교직원 및 학교법인의 임직원, 언론사 대표 및 임직원은 제외)</li></ol><h1 id="나-원고-규격별-지급단가" tabindex="-1"><strong>나. 원고 규격별 지급단가</strong> <a class="header-anchor" href="#나-원고-규격별-지급단가" aria-label="Permalink to &quot;**나. 원고 규격별 지급단가**&quot;">​</a></h1><table><colgroup><col style="width:17%;"><col style="width:54%;"><col style="width:27%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>원고 형식</strong></p></th><th style="text-align:center;"><p><strong>지급 규격</strong></p></th><th style="text-align:center;"><p><strong>지 급 액</strong></p></th></tr></thead><tbody><tr><td style="text-align:center;"><p>원고지</p></td><td><p>∘ 200자 원고지 3.5매를 A4 용지 1면으로 산정</p></td><td style="text-align:center;"><p>1매당 12,000원</p></td></tr><tr><td style="text-align:center;"><p>A4 용지</p></td><td><p>∘ 글자크기 13p, 줄 간격 160%,</p><p>∘ 상하여백 15, 좌우여백 25, 머리말·꼬리말 15</p><p>∘ 또는 1면 기준 300단어</p></td><td style="text-align:center;"><p>42,000원</p><p>(원고지 3.5매 기준)</p></td></tr><tr><td style="text-align:center;"><p>파워포인트</p></td><td><p>∘ 슬라이드 2면을 A4 용지 1면으로 산정</p></td><td style="text-align:center;"><p>2면당 42,000원</p></td></tr></tbody></table><p>주) 1. 1매에 27행을 기준으로 30%미만 작성된 매수는 지급매수로 산정하지 아니함</p><ul><li><p>그림, 도표 등은 그 그림, 도표 등이 A4용지 면당 차지하는 행을 기준으로 산정</p></li><li><p>단순히 부록으로 관련법규를 발췌하여 편집하였을 때에는 원고료 산정에서 제외</p></li></ul><ol start="2"><li><p>신규 원고 매수만 원고료 지급(수정 원고는 미반영)</p></li><li><p>청탁금지법에 따른 공직자등 출강강사의 경우 원고료 미지급(다만, 법제2조제2항 다목 및 라목의 각급 학교의 장과 교직원 및 학교법인의 임직원, 언론사 대표 및 임직원은 제외)</p></li><li><p>원고 면별 글자 수 및 종류(평론, 현장 취재 등) 등을 감안하여 지급기준의 20% 범위 내에서 감액 또는 증액 가능 (원고지 1매 기준: 9,600원~14,400원)</p></li></ol><p>※ 위 기준단가로 책정하기 어려운 특수 상황일 경우, 대표이사 방침 등을 통해 별도 책정 가능 (근거 必)</p><h1 id="다-정기간행물-기타원고-지급단가-※정기간행물에만-적용가능" tabindex="-1"><strong>다. 정기간행물 기타원고 지급단가 (※정기간행물에만 적용가능)</strong> <a class="header-anchor" href="#다-정기간행물-기타원고-지급단가-※정기간행물에만-적용가능" aria-label="Permalink to &quot;**다. 정기간행물 기타원고 지급단가 (※정기간행물에만 적용가능)**&quot;">​</a></h1><table><colgroup><col style="width:11%;"><col style="width:26%;"><col style="width:8%;"><col style="width:25%;"><col style="width:28%;"></colgroup><thead><tr><th colspan="2" style="text-align:center;"><p><strong>구분</strong></p></th><th style="text-align:center;"><p><strong>단위</strong></p></th><th style="text-align:center;"><p><strong>단가</strong></p></th><th style="text-align:center;"><strong>비고</strong></th></tr></thead><tbody><tr><td rowspan="5"><p>원고료</p></td><td style="text-align:center;"><p>인터뷰 사례비</p></td><td style="text-align:center;"><p>회</p></td><td style="text-align:center;"><p>150,000</p></td><td></td></tr><tr><td rowspan="2" style="text-align:center;"><p>시</p></td><td style="text-align:center;"><p>신작</p></td><td style="text-align:center;"><p>200,000</p></td><td rowspan="2"></td></tr><tr><td style="text-align:center;"><p>재수록</p></td><td style="text-align:center;"><p>100,000</p></td></tr><tr><td rowspan="2" style="text-align:center;"><p>콩트·희곡</p></td><td style="text-align:center;"><p>신작</p></td><td style="text-align:center;"><p>300,000</p></td><td rowspan="2"></td></tr><tr><td style="text-align:center;"><p>재수록</p></td><td style="text-align:center;"><p>100,000</p></td></tr><tr><td rowspan="4"><p>일러스트료</p></td><td style="text-align:center;"><p>표지용</p></td><td rowspan="4" style="text-align:center;"><p>컷</p></td><td style="text-align:center;"><p>500,000</p></td><td></td></tr><tr><td style="text-align:center;"><p>스토리형</p></td><td style="text-align:center;"><p>200,000</p></td><td></td></tr><tr><td style="text-align:center;"><p>단순형</p></td><td style="text-align:center;"><p>100,000</p></td><td></td></tr><tr><td style="text-align:center;"><p>표제컷</p></td><td style="text-align:center;"><p>50,000</p></td><td></td></tr><tr><td rowspan="4"><p>사진료</p></td><td style="text-align:center;"><p>대여 사진(언론사 등)</p></td><td rowspan="4" style="text-align:center;"><p>컷</p></td><td style="text-align:center;"><p>대여사 규정</p></td><td></td></tr><tr><td style="text-align:center;"><p>독자 투고 사진</p></td><td style="text-align:center;"><p>50,000</p></td><td></td></tr><tr><td style="text-align:center;"><p>청탁원고에 부가되는 사진</p></td><td style="text-align:center;"><p>50,000</p></td><td style="text-align:center;">필자 촬영 제공</td></tr><tr><td style="text-align:center;"><p>현장 취재 사진</p></td><td style="text-align:center;"><p>150,000</p></td><td style="text-align:center;">발주에 의한 경우</td></tr></tbody></table><p>주) 1. 정기간행물이란, 끝나는 시기가 정해지지 않고 일정한 기간을 두고 연속적으로 발행되는 간행물로 연 2회 이상 계속적으로 발행되어야 함</p><ol start="2"><li><p>정기간행물의 원고 외 매체 음원, 영상 등은 상기의 기준을 준용하여 지급할 수 있으며, 창작 비용에 대한 별도비용 필요 시 시중가격 적용</p></li><li><p>인터뷰 사례비는 인터뷰어 및 인터뷰이를 포함하며, 인터뷰어는 원고료 미지급 시에만 책정가능</p></li><li><p>문화체육관광부 「홍보콘텐츠 제작비 지급에 관한 규정」을 일부 준용함</p></li></ol><h1 id="라-기타-원고-지급비율" tabindex="-1"><strong>라. 기타 원고 지급비율</strong> <a class="header-anchor" href="#라-기타-원고-지급비율" aria-label="Permalink to &quot;**라. 기타 원고 지급비율**&quot;">​</a></h1><table><colgroup><col style="width:25%;"><col style="width:46%;"><col style="width:28%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>구분</strong></p></th><th style="text-align:center;"><p><strong>기 준</strong></p></th><th style="text-align:center;"><p><strong>지급 비율</strong></p></th></tr></thead><tbody><tr><td rowspan="3"><p>기존 원고 활용</p></td><td><p>30% 미만 수정</p></td><td style="text-align:center;">미지급</td></tr><tr><td><p>30% 이상~70% 미만 수정</p></td><td style="text-align:center;">50% 지급</td></tr><tr><td><p>70% 이상 수정</p></td><td style="text-align:center;"><p>100% 지급</p></td></tr><tr><td><p>A4 용지 1/2이하</p></td><td><p>20줄을 1면으로 환산</p></td><td rowspan="2" style="text-align:center;"><p>각 원고를 합산하여 지급</p></td></tr><tr><td><p>200자 원고지 5행 이하</p></td><td><p>10행을 1매로 환산</p></td></tr><tr><td colspan="2"><p>참고문헌, 부록 등을 워드로 작성하여 제출</p></td><td style="text-align:center;">30% 지급</td></tr><tr><td colspan="2" style="text-align:center;"><p>복사물, 표지, 목차, 간지</p></td><td style="text-align:center;">미지급</td></tr></tbody></table><p>기타</p><p><strong>7</strong></p><h1 id="가-대관료" tabindex="-1"><strong>가. 대관료</strong> <a class="header-anchor" href="#가-대관료" aria-label="Permalink to &quot;**가. 대관료**&quot;">​</a></h1><ul><li>세미나실, 회의장, 공연장 등 대관의 경우 대관사의 책정기준에 따라 지급하되, 회의장 임차는 공공기관을 우선 활용할 것</li></ul><p>(예: 학교시설, 구민회관, 공공 문화시설 등)</p><p><strong><u>[참고1] 외부강의 등 사례금 상한액</u></strong> ※부정청탁 및 금품 등 수수의 금지에 관한 법률 시행령 &lt;별표 2&gt;</p><h3 id="외부강의등-사례금-상한액-시행령-제25조-관련" tabindex="-1"><strong>외부강의등 사례금 상한액(시행령 제25조 관련)</strong> <a class="header-anchor" href="#외부강의등-사례금-상한액-시행령-제25조-관련" aria-label="Permalink to &quot;**외부강의등 사례금 상한액(시행령 제25조 관련)**&quot;">​</a></h3><ol><li><strong>공직자등별 사례금 상한액</strong></li></ol><p>가. 법 제2조제2호가목 및 나목에 따른 공직자등(같은 호 다목에 따른 각급 학교의 장과 교직 원 및 같은 호 라목에 따른 공직자등에도 해당하는 사람은 제외한다): 40만원</p><p>나. 법 제2조제2호다목 및 라목에 따른 공직자등: 100만원</p><p>다. 가목 및 나목에도 불구하고 국제기구, 외국정부, 외국대학, 외국연구기관, 외국학술단체, 그 밖에 이에 준하는 외국기관에서 지급하는 외부강의등의 사례금 상한액은 사례금을 지급하는 자의 지급기준에 따른다.</p><h3 id="적용기준" tabindex="-1"><strong>적용기준</strong> <a class="header-anchor" href="#적용기준" aria-label="Permalink to &quot;**적용기준**&quot;">​</a></h3><p>가. 제1호가목 및 나목의 상한액은 강의 등의 경우 1시간당, 기고의 경우 1건당 상한액으로 한 다.</p><p>나. 제1호가목에 따른 공직자등은 1시간을 초과하여 강의 등을 하는 경우에도 사례금 총액은 강의시간에 관계없이 1시간 상한액의 100분의 150에 해당하는 금액을 초과하지 못한다.</p><p>다. 제1호가목 및 나목의 상한액에는 강의료, 원고료, 출연료 등 명목에 관계없이 외부강의등 사례금 제공자가 외부강의등과 관련하여 공직자등에게 제공하는 일체의 사례금을 포함한다.</p><p>라. 다목에도 불구하고 공직자등이 소속기관에서 교통비, 숙박비, 식비 등 여비를 지급받지 못한 경우에는 「공무원 여비 규정」 등 공공기관별로 적용되는 여비 규정의 기준 내에서 실비수 준으로 제공되는 교통비, 숙박비 및 식비는 제1호의 사례금에 포함되지 않는다.</p><p><strong><u>[참고2] 음식물ㆍ경조사비ㆍ선물 등의 가액 범위</u></strong></p><p>※부정청탁 및 금품 등 수수의 금지에 관한 법률 시행령 &lt;별표 1&gt;</p><h3 id="음식물ᆞ경조사비ᆞ선물-등의-가액-범위-시행령-제17조제1항-관련" tabindex="-1"><strong>음식물ㆍ경조사비ㆍ선물 등의 가액 범위(시행령 제17조제1항 관련)</strong> <a class="header-anchor" href="#음식물ᆞ경조사비ᆞ선물-등의-가액-범위-시행령-제17조제1항-관련" aria-label="Permalink to &quot;**음식물ㆍ경조사비ㆍ선물 등의 가액 범위(시행령 제17조제1항 관련)**&quot;">​</a></h3><ol><li><p>음식물(제공자와 공직자등이 함께 하는 식사, 다과, 주류, 음료, 그 밖에 이에 준하는 것을 말한다): 5만원</p></li><li><p>경조사비: 축의금ㆍ조의금은 5만원. 다만, 축의금ㆍ조의금을 대신하는 화환ㆍ조화는 10만원으 로 한다.</p></li><li><p>선물: 다음 각 목의 금품등을 제외한 일체의 물품, 상품권(물품상품권 및 용역상품권만 해당 하며, 이하 “상품권”이라 한다) 및 그 밖에 이에 준하는 것은 5만원. 다만, 「농수산물 품질관 리법」 제2조제1항제1호에 따른 농수산물(이하 “농수산물”이라 한다) 및 같은 항 제13호에 따른 농수산가공품(농수산물을 원료 또는 재료의 50퍼센트를 넘게 사용하여 가공한 제품만 해당하며, 이하 “농수산가공품”이라 한다)과 농수산물ㆍ농수산가공품 상품권은 15만원(제17조 제2항에 따른 기간 중에는 30만원)으로 한다.</p></li></ol><p>가. 금전</p><p>나. 유가증권(상품권은 제외한다) 다. 제1호의 음식물</p><p>라. 제2호의 경조사비</p><h3 id="비-고" tabindex="-1"><strong>비 고</strong> <a class="header-anchor" href="#비-고" aria-label="Permalink to &quot;**비 고**&quot;">​</a></h3><p>가. 제1호, 제2호 본문ㆍ단서 및 제3호 본문ㆍ단서에서 규정하는 각각의 가액 범위는 각각에 해 당하는 것을 모두 합산한 금액으로 한다.</p><p>나. 제2호 본문의 축의금ㆍ조의금과 같은 호 단서의 화환ㆍ조화를 함께 받은 경우에는 그 가액 을 합산한다. 이 경우 가액 범위는 10만원으로 하되, 제2호 본문 또는 단서의 가액 범위를 각각 초과해서는 안 된다.</p><p>다. 제3호에서 “상품권”이란 그 명칭 또는 형태에 관계없이 발행자가 특정한 물품 또는 용역의 수량을 기재(전자적 또는 자기적 방법에 의한 기록을 포함한다)하여 발행ㆍ판매하고, 그 소 지자가 발행자 또는 발행자가 지정하는 자(이하 “발행자등”이라 한다)에게 이를 제시 또는 교부하거나 그 밖의 방법으로 사용함으로써 그 증표에 기재된 내용에 따라 발행자등으로부 터 해당 물품 또는 용역을 제공받을 수 있는 증표인 물품상품권 또는 용역상품권을 말하며, 백화점상품권ㆍ온누리상품권ㆍ지역사랑상품권ㆍ문화상품권 등 일정한 금액이 기재되어 소지 자가 해당 금액에 상응하는 물품 또는 용역을 제공받을 수 있는 증표인 금액상품권은 제외 한다.</p><p>라. 제3호 본문의 선물과 같은 호 단서의 농수산물ㆍ농수산가공품 또는 농수산물ㆍ농수산가공품 상품권을 함께 받은 경우에는 그 가액을 합산한다. 이 경우 가액 범위는 15만원(제17조제2 항에 따른 기간 중에는 30만원)으로 하되, 제3호 본문 또는 단서의 가액 범위를 각각 초과 해서는 안 된다.</p><p>마. 제1호의 음식물, 제2호의 경조사비 및 제3호의 선물 중 2가지 이상을 함께 받은 경우에는 그 가액을 합산한다. 이 경우 가액 범위는 함께 받은 음식물, 경조사비 및 선물의 가액 범 위 중 가장 높은 금액으로 하되, 제1호부터 제3호까지의 규정에 따른 가액 범위를 각각 초 과해서는 안 된다.</p>',138)]))}const y=r(n,[["render",d]]);export{c as __pageData,y as default};
